/* Mirror successful web receipts. Ledger stays local until the API accepts it. */
(()=>{let sent='',running=false,timer,last='';
function status(text){last=text;let el=document.getElementById('finance-sync');if(!el){el=document.createElement('a');el.id='finance-sync';el.href='../finance/';el.style.cssText='font-size:11px;color:#0b4f94;max-width:180px';document.querySelector('.top-actions')?.prepend(el)}el.textContent=text;el.title='Thu ngân web → dữ liệu tài chính và thông báo app'}
async function sync(){if(running)return;const P=window.Pema;if(!P)return;const invoices=P.state.patients.flatMap(p=>p.invoices.map(i=>({id:i.id,patient:p.id,name:p.name,date:i.date,amount:i.amount,received:i.paid?i.amount:Math.min(i.amount,i.received||0)})));const payments=P.state.operations?.payments||[];const body=JSON.stringify({invoices,payments});if(body===sent){status(last);return}running=true;status('Đang đồng bộ tài chính…');try{const r=await fetch('http://127.0.0.1:4174/command/sync',{method:'POST',headers:{'Content-Type':'application/json','X-Pema-Role':'accountant','X-Pema-Doctor':'D0'},body,signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error();sent=body;status('Tài chính đã đồng bộ')}catch{status('Tài chính chờ kết nối · thử lại')}finally{running=false}}
window.addEventListener('pema-change',()=>{clearTimeout(timer);timer=setTimeout(sync,300)});window.addEventListener('pema-external',sync);setInterval(sync,10000);sync();})();
